'use strict';
// L10-J: the Figma adapter against the baseline `figma-import.js` oracle (tests/fixtures/native-import-adapters/figma-walk.json, generated by
// tools/gen_figma.mjs from fbe4b8a3 by running the verbatim source). Parsing stays Figma's REST JSON; vector geometry reaches Paper through
// the SVG adapter; text and image fills are typed `unavailable` rows, never dropped and never faked.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const figma = require('../src/js/adapters/native-import-figma.js');
const svg = require('../src/js/adapters/native-import-svg.js');
const coreModule = require('../src/js/adapters/native-import-core.js');
const helper = require('./helpers/native-import-paper.cjs');
const { makeSession, makePorts } = require('./helpers/native-import-session.cjs');

const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'native-import-adapters', 'figma-walk.json'), 'utf8'));
const ADAPTER = path.join(__dirname, '..', 'src', 'js', 'adapters', 'native-import-figma.js');
const TEMPLATES = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'native-import-adapters', 'svg-flows.json'), 'utf8')).templates;
const CANVAS = { w: 1920, h: 1080 };
const paper = helper.load();
const J = (v) => JSON.stringify(v);

function load(edits) {
  let source = fs.readFileSync(ADAPTER, 'utf8');
  for (const [from, to] of edits || []) {
    assert.equal(source.split(from).length, 2, `mutation anchor must occur exactly once: ${from}`);
    source = source.replace(from, to);
  }
  const m = { exports: {} };
  new Function('module', 'exports', 'require', source)(m, m.exports, (name) => (name === './native-import-svg.js' ? svg : require(name)));
  return m.exports;
}
// Everything the oracle row records, rebuilt from the plan (the font key is a provider answer the plan does not hold).
function observed(mod, flow) {
  const plan = mod.convert(flow.json, flow.opts, CANVAS);
  return {
    layers: plan.frames.map((f) => f.layerName),
    resize: plan.resize ? [plan.resize] : [],
    svg: plan.frames.filter((f) => f.svgText).map((f) => ({ text: f.svgText, noFit: true })),
    texts: plan.frames.flatMap((f) => f.texts).map((t) => ({ text: t.text, size: t.size, color: t.color, align: t.align, width: t.width, x: t.x, y: t.y, bold: t.bold, italic: t.italic, lineHeightMult: t.lineHeightMult, letterSpacing: t.letterSpacing })),
    families: plan.frames.flatMap((f) => f.texts).map((t) => t.family).filter(Boolean),
    images: plan.frames.flatMap((f) => f.images).map((i) => ({ url: 'data:fake;base64,' + i.source, w: i.width, h: i.height, x: i.x, y: i.y, opacity: i.opacity })),
    skipped: plan.skipped, frames: plan.frames.length,
  };
}
const expected = (flow) => {
  const e = flow.expect;
  return { layers: e.layers, resize: e.resize, svg: e.svg, texts: e.texts.map(({ fontKey, ...rest }) => rest), families: e.fonts, images: e.images, skipped: e.report.skipped, frames: e.report.framesImported };
};

test('fixture pins the baseline commit and its row counts', () => {
  assert.equal(FIX.meta.baseline, 'fbe4b8a33e6d5a229f014154df2ba21988a9fabc');
  assert.deepEqual(FIX.meta.counts, { flows: 37, glue: 13, parse: 14, nodes: 16, matrices: 36 });
});

test('file key, node id and the 2x3 matrix helpers equal the baseline on every row', () => {
  for (const r of FIX.parse) assert.equal(figma.parseFileKey(r.input && r.input.undefined ? undefined : r.input), r.key, J(r.input));
  for (const r of FIX.nodes) {
    const input = r.input && r.input.undefined ? undefined : r.input;
    if (r.error) assert.throws(() => figma.parseNodeId(input), (e) => e.name === r.error, J(r.input));
    else assert.equal(figma.parseNodeId(input), r.value, J(r.input));
  }
  for (const r of FIX.matrices) {
    const out = r.op === 'mul' ? figma.matMultiply(r.m, r.n) : r.op === 'inv' ? figma.matInvert(r.m) : figma.nodeAbsMatrix(r.node);
    assert.deepEqual(JSON.parse(J(out)), r.out, J(r));
  }
});

test('every baseline file converts to the same layers, canvas resize, SVG strings, text and image requests and skip messages', () => {
  for (const flow of FIX.flows) assert.deepEqual(JSON.parse(J(observed(figma, flow))), JSON.parse(J(expected(flow))), flow.id);
  assert.deepEqual(FIX.flows.map((f) => f.id).filter((id) => /regression/.test(id)), ['image-beats-fill-geometry-regression']);
});

test('the REST glue sends the baseline requests in the baseline order and fails with the baseline messages', async () => {
  for (const g of FIX.glue) {
    const fetches = [];
    const fetchFn = async (url, init) => {
      fetches.push({ url, headers: init && init.headers ? init.headers : null });
      const kind = /\/nodes\?/.test(url) ? 'nodes' : /\/images$/.test(url) ? 'images' : 'files';
      const r = g.responses[kind];
      if (!r) throw new Error('unexpected request ' + url);
      if (r.throws) throw new Error('network down');
      return { ok: r.ok, status: r.status, json: async () => r.json };
    };
    let outcome;
    try {
      const got = await figma.fetchFigma(fetchFn, g.input, g.token, {});
      const plan = figma.convert(got.figmaJson, got.opts, CANVAS);
      outcome = { layers: plan.frames.map((f) => f.layerName), svgCount: plan.frames.filter((f) => f.svgText).length };
    } catch (e) { outcome = { error: e.message }; }
    assert.deepEqual(fetches, g.expect.fetches, g.id);
    if (g.expect.outcome.error) assert.deepEqual(outcome, { error: g.expect.outcome.error }, g.id);
    else assert.deepEqual(outcome, { layers: g.expect.layers, svgCount: g.expect.svgCount }, g.id);
  }
});

// A mini SVG reader for exactly the strings the walk emits: <path transform="matrix(..)" d="M..L..Z" fill="rgba(..)"/> (Paper's own
// parser needs a DOM). It builds the tree project.importSVG would return, with the matrix applied as Paper applies it.
function miniSvg(text) {
  const group = new paper.Group({ insert: false, applyMatrix: false });
  const tag = /<path transform="matrix\(([^)]*)\)" d="([^"]*)" fill-rule="[a-z]+" fill="rgba\((\d+),(\d+),(\d+),([\d.]+)\)"\/>/g;
  let m;
  while ((m = tag.exec(text))) {
    const p = new paper.Path({ insert: false });
    const cmds = m[2].match(/[MLZ][^MLZ]*/g) || [];
    for (const c of cmds) {
      const [x, y] = c.slice(1).trim().split(/\s+/).map(Number);
      if (c[0] === 'M' || c[0] === 'L') p.add(new paper.Point(x, y));
      else p.closed = true;
    }
    p.transform(new paper.Matrix(...m[1].split(' ').map(Number)));
    p.fillColor = new paper.Color(Number(m[3]) / 255, Number(m[4]) / 255, Number(m[5]) / 255, Number(m[6]));
    group.addChild(p);
  }
  return group;
}
async function importFile(flow, sessionOptions, extra) {
  const h = makeSession(sessionOptions);
  const { ports } = makePorts(h, { maxRequestBytes: 1 << 20 });
  const resized = [], toasts = [];
  const adapter = figma.create({
    paper: helper.port(paper, (text) => miniSvg(text)), core: coreModule.create(ports), t: (k) => TEMPLATES.en[k],
    notify: (m) => toasts.push(m), resizeCanvas: async (w, hh) => { resized.push([w, hh]); return 'applied'; }, fetch: undefined,
  });
  const result = await adapter.importFile(flow.json, Object.assign({}, flow.opts, extra));
  return { result, h, resized, toasts };
}
const flowOf = (id) => FIX.flows.find((f) => f.id === id);

test('a vector-only file publishes once: one layer per frame, frame-local records, then the canvas resize', async () => {
  const one = await importFile(flowOf('one-frame-one-shape'));
  assert.equal(one.result.status, 'imported');
  assert.equal(one.h.calls.length, 1, 'ONE dispatch');
  assert.deepEqual(one.h.calls[0].layers, [{ sourceId: 'figma:0', name: 'Home' }]);
  const [rec] = one.h.calls[0].records;
  assert.equal(rec.sourceId, 'figma:0:svg:1:0');
  assert.equal(rec.record.target.layerUid, 'figma:0', 'records name their layer by its source id, the owner maps it');
  assert.deepEqual(rec.record.geometry.segments.map((s) => [s.point.x, s.point.y]), [[20, 20], [30, 20], [30, 30], [20, 30]], 'frame-local: (120,220) minus the frame origin (100,200)');
  assert.deepEqual(rec.record.fill, { kind: 'solid', r: 1, g: 0, b: 0, a: 1 });
  assert.deepEqual(one.result.layers, [{ sourceId: 'figma:0', layerUid: 'native-layer:8:0' }]);
  assert.deepEqual(one.result.report, { framesImported: 1, shapesImported: 1, textsImported: 0, imagesImported: 0, skipped: [] });
  assert.deepEqual(one.resized, [[400, 300]], 'the first frame sizes the canvas, after the commit');
  assert.deepEqual(one.result.canvasResize, { status: 'applied', width: 400, height: 300 });
  assert.equal(one.result.selected, true);
  const two = await importFile(flowOf('two-frames-first-sets-canvas'));
  assert.deepEqual(two.h.calls[0].layers.map((l) => l.name), ['A', 'B']);
  assert.deepEqual(two.result.report.framesImported, 2);
  assert.deepEqual(two.h.calls[0].records.map((r) => [r.sourceId, r.record.target.layerUid]), [['figma:0:svg:1:0', 'figma:0'], ['figma:1:svg:1:0', 'figma:1']]);
});

test('every vector-only baseline file imports as many records as the baseline imported shapes', async () => {
  let checked = 0;
  for (const flow of FIX.flows) {
    const e = flow.expect;
    if (e.texts.length || e.images.length || !e.layers.length) continue;
    const out = await importFile(flow);
    assert.equal(out.result.status, 'imported', flow.id);
    assert.equal(out.h.calls[0].records.length, e.report.shapesImported, `${flow.id}: shapes`);
    assert.deepEqual(out.h.calls[0].layers.map((l) => l.name), e.layers, `${flow.id}: layers`);
    assert.deepEqual(out.resized, e.resize, `${flow.id}: canvas`);
    assert.deepEqual(out.h.calls[0].skipped.map((s) => s.reason), e.report.skipped, `${flow.id}: the walk's skipped elements are typed skips`);
    checked += 1;
  }
  assert.ok(checked >= 20, `checked ${checked}`);
});

test('a rotated frame keeps the layout: the frame inverse and the node matrix compose to exact anchors', async () => {
  const out = await importFile(flowOf('rotated-frame-inverse'));
  const [rec] = out.h.calls[0].records;
  assert.deepEqual(rec.record.geometry.segments.map((s) => [s.point.x, s.point.y]), [[30, 180], [30, 170], [40, 170], [40, 180]], 'matrix(0 -1 1 0 30 180) applied to the 10x10 square');
});

test('text blocks and image fills are typed unavailable rows: the owner refuses the batch and nothing is published or resized', async () => {
  for (const id of ['text-variants', 'mixed-everything', 'image-fill-with-imagemap']) {
    const out = await importFile(flowOf(id));
    assert.equal(out.result.status, 'unavailable', id);
    assert.equal(out.result.reason, 'native_refused');
    assert.equal(out.h.state.contentRevision, 7, id);
    assert.deepEqual(out.resized, [], `${id}: the canvas is not touched when nothing was imported`);
    assert.deepEqual(out.toasts, [], 'no success toast');
    assert.equal(out.result.report.framesImported, 0);
  }
  const mixed = await importFile(flowOf('mixed-everything'));
  assert.deepEqual(mixed.h.calls[0].unavailable, [
    { sourceId: 'figma:0:text:0', need: 'text' }, { sourceId: 'figma:0:font:0', need: 'font' }, { sourceId: 'figma:0:image:0', need: 'raster-asset' },
  ]);
  assert.deepEqual(mixed.result.unavailable, ['text', 'font', 'raster-asset']);
  assert.deepEqual(mixed.h.calls[0].layers, [{ sourceId: 'figma:0', name: 'Mix' }]);
  assert.equal(mixed.h.calls[0].records.length, 1, 'the vector part travels with the batch; the owner refuses it as a whole');
  const noMap = await importFile(flowOf('image-fill-no-imagemap'));
  assert.equal(noMap.result.status, 'imported', 'an image fill with no imageMap is reported, as the baseline did, and nothing needs a provider');
  assert.deepEqual(noMap.h.calls[0].skipped.map((s) => s.reason), ['2 image fill(s) skipped — pass opts.imageMap (GET /v1/files/:key/images) to import them']);
  const nothing = await importFile(flowOf('scoped-without-artboard'));
  assert.equal(nothing.result.status, 'nothing');
  assert.equal(nothing.h.calls.length, 0);
  assert.deepEqual(nothing.result.report.skipped, [figma.NO_ARTBOARD]);
});

test('the settings-panel run fetches, imports and toasts with the baseline strings; failures are toasted and typed', async () => {
  const g = FIX.glue.find((x) => x.id === 'file-url');
  const h = makeSession();
  const toasts = [];
  const fetchFn = async (url) => ({ ok: true, status: 200, json: async () => (/\/images$/.test(url) ? { images: {} } : g.responses.files.json) });
  const adapter = figma.create({ paper: helper.port(paper, (text) => miniSvg(text)), core: coreModule.create(makePorts(h, { maxRequestBytes: 1 << 20 }).ports), t: (k) => TEMPLATES.en[k], notify: (m) => toasts.push(m), fetch: fetchFn });
  const ok = await adapter.run('https://www.figma.com/design/AbC123/My-file', 'tok', {});
  assert.equal(ok.status, 'imported');
  assert.deepEqual(toasts, ['Import Figma…', '1 vector shape(s) imported', '1 frame(s), 1 forme(s), 0 texte(s), 0 image(s) importé(s)']);
  assert.equal(figma.summaryMessage({ framesImported: 2, shapesImported: 3, textsImported: 0, imagesImported: 0, skipped: ['a'] }), '2 frame(s), 3 forme(s), 0 texte(s), 0 image(s) importé(s) — 1 élément(s) ignoré(s) (voir console)');
  toasts.length = 0;
  const failed = await adapter.run('', 'tok', {});
  assert.equal(failed.status, 'failed');
  assert.deepEqual(toasts, ['Import Figma…', 'Import Figma échoué : URL ou clé de fichier Figma invalide']);
  assert.equal(h.calls.length, 1, 'the failed run published nothing');
});

test('without a presented native session nothing is converted, fetched for pixels or published', async () => {
  const out = await importFile(flowOf('one-frame-one-shape'), { declared: false });
  assert.deepEqual(out.result, { status: 'unavailable', reason: 'native_declaration_absent' });
  assert.deepEqual(out.resized, []);
});

// ---- negative controls: one source edit each; the oracle comparison that owns the rule must reject it ----
function mismatches(mod) {
  let bad = 0;
  for (const r of FIX.matrices) {
    const out = r.op === 'mul' ? mod.matMultiply(r.m, r.n) : r.op === 'inv' ? mod.matInvert(r.m) : mod.nodeAbsMatrix(r.node);
    if (J(out) !== J(r.out)) bad += 1;
  }
  for (const flow of FIX.flows) { try { if (J(observed(mod, flow)) !== J(expected(flow))) bad += 1; } catch (_) { bad += 1; } }
  return bad;
}
function nodeIdMismatch(mod) {
  let bad = 0;
  for (const r of FIX.nodes) {
    const input = r.input && r.input.undefined ? undefined : r.input;
    try { if (!r.error && mod.parseNodeId(input) !== r.value) bad += 1; } catch (_) { bad += r.error ? 0 : 1; }
  }
  return bad;
}
test('controls: the unmutated adapter has no mismatch and every source mutation is rejected', () => {
  assert.equal(mismatches(figma), 0);
  assert.equal(nodeIdMismatch(figma), 0);
  const mutants = [
    ['bottom-most solid paint wins', [['for (let i = paints.length - 1; i >= 0; i--) { const p = paints[i]; if (p && p.visible !== false && p.type === \'SOLID\') return p; }', 'for (let i = 0; i < paints.length; i++) { const p = paints[i]; if (p && p.visible !== false && p.type === \'SOLID\') return p; }']]],
    ['hidden paints count', [["if (p && p.visible !== false && p.type === 'SOLID') return p;", "if (p && p.type === 'SOLID') return p;"]]],
    ['image fill loses to fill geometry', [['if (imagePaint) {', 'if (false) {']]],
    ['image stroke dropped', [['if (imgStrokeCss) out.svgTags', 'if (false) out.svgTags']]],
    ['invisible nodes walked', [['if (!node || node.visible === false) return;', 'if (!node) return;']]],
    ['frame inverse not applied', [['const mat = matMultiply(frameInv, nodeAbsMatrix(node));', 'const mat = nodeAbsMatrix(node);']]],
    ['singular matrix not guarded', [['if (!det) return matIdentity();', '']]],
    ['alpha not clamped', [['const a = clamp01((paint.opacity', 'const a = ((paint.opacity']]],
    ['channels not rounded', [['Math.round(clamp01(c.r) * 255)', 'clamp01(c.r) * 255']]],
    ['winding rules not grouped', [["const rule = g.windingRule === 'EVENODD' ? 'evenodd' : 'nonzero';", "const rule = 'nonzero';"]]],
    ['resize follows the first VISIBLE frame', [['if (fi === 0 && bb && bb.width > 0 && bb.height > 0)', 'if (plan.frames.length === 0 && bb && bb.width > 0 && bb.height > 0)']]],
    ['resize not rounded', [['plan.resize = [Math.round(bb.width), Math.round(bb.height)];', 'plan.resize = [bb.width, bb.height];']]],
    ['unnamed frame keeps no counter', [["frame.name || ('Figma ' + (fi + 1))", "frame.name || 'Figma'"]]],
    ['invisible frames imported', [['if (frame.visible === false) continue;', '']]],
    ['frame names ignored', [['if (opts.frameNames && opts.frameNames.length) frames = frames.filter((f) => opts.frameNames.indexOf(f.name) >= 0);', '']]],
    ['page index ignored', [['doc.children[opts.pageIndex || 0] || doc.children[0]', 'doc.children[0]']]],
    ['bold threshold', [['(t.style.fontWeight || 400) >= 700', '(t.style.fontWeight || 400) > 700']]],
    ['line height multiplier', [['(lhPx && size) ? (lhPx / size) : null', 'null']]],
    ['text width dropped', [['width: t.w || null', 'width: null']]],
    ['empty text imported', [['out.texts.filter((t) => t.text)', 'out.texts']]],
    ['image size not clamped', [['width: Math.max(1, img.w)', 'width: img.w']]],
    ['image without map entry not reported', [["if (!source) { skipped.push('IMAGE fill (' + img.name + '): no imageMap entry for ' + img.imageRef); return; }", 'if (!source) return;']]],
    ['skipped summary dropped', [['else if (out.images.length) skipped.push(', 'else if (false) skipped.push(']]],
    ['selection id keeps the dash', [["if (raw.indexOf(':') < 0) raw = raw.replace('-', ':');", '']]],
  ];
  for (const [name, edits] of mutants) assert.ok(mismatches(load(edits)) > 0 || nodeIdMismatch(load(edits)) > 0, `mutation not caught: ${name}`);
});
